SELECT nr.Version AS id_external FROM DEPS_DEV_V1.NUGETREQUIREMENTS nr WHERE CAST(nr.DependencyGroups AS CHAR) LIKE '%good%' ORDER BY nr.SnapshotAt DESC LIMIT 10;
SELECT nr.Version AS id_external FROM DEPS_DEV_V1.NUGETREQUIREMENTS nr WHERE FROM_UNIXTIME(nr.SnapshotAt / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(nr.SnapshotAt / 1000000) < '2026-01-31 23:59:59' ORDER BY nr.SnapshotAt DESC LIMIT 10;
SELECT COUNT(*) AS event_cnt FROM DEPS_DEV_V1.NUGETREQUIREMENTS nr WHERE FROM_UNIXTIME(nr.SnapshotAt / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(nr.SnapshotAt / 1000000) < '2026-01-31 23:59:59';
SELECT COUNT(DISTINCT CAST(d.Dependent AS CHAR)) AS distinct_entity_cnt FROM DEPS_DEV_V1.DEPENDENTS d WHERE FROM_UNIXTIME(d.SnapshotAt / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(d.SnapshotAt / 1000000) < '2026-01-31 23:59:59';
SELECT d.System AS category_topic, COUNT(*) AS event_cnt FROM DEPS_DEV_V1.DEPENDENTS d WHERE FROM_UNIXTIME(d.SnapshotAt / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(d.SnapshotAt / 1000000) < '2026-01-31 23:59:59' GROUP BY d.System ORDER BY event_cnt DESC LIMIT 10;
SELECT d.System AS category_topic, COUNT(DISTINCT CAST(d.Dependent AS CHAR)) AS distinct_entity_cnt FROM DEPS_DEV_V1.DEPENDENTS d WHERE FROM_UNIXTIME(d.SnapshotAt / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(d.SnapshotAt / 1000000) < '2026-01-31 23:59:59' GROUP BY d.System ORDER BY distinct_entity_cnt DESC LIMIT 10;
SELECT d.Name AS name_entity, COUNT(*) AS event_cnt FROM DEPS_DEV_V1.DEPENDENTS d WHERE FROM_UNIXTIME(d.SnapshotAt / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(d.SnapshotAt / 1000000) < '2026-01-31 23:59:59' GROUP BY d.Name ORDER BY event_cnt DESC LIMIT 10;
SELECT DATE(FROM_UNIXTIME(d.SnapshotAt / 1000000.0)) AS day, COUNT(*) AS event_cnt FROM DEPS_DEV_V1.DEPENDENTS d WHERE d.SnapshotAt >= UNIX_TIMESTAMP('2001-01-01 00:00:00') * 1000000.0 AND d.SnapshotAt < UNIX_TIMESTAMP('2026-01-31 23:59:59') * 1000000.0 GROUP BY day ORDER BY day;
SELECT DATE(FROM_UNIXTIME(d.SnapshotAt / 1000000.0)) AS day, d.System AS category_topic, COUNT(*) AS event_cnt FROM DEPS_DEV_V1.DEPENDENTS d WHERE FROM_UNIXTIME(d.SnapshotAt / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(d.SnapshotAt / 1000000) < '2026-01-31 23:59:59' GROUP BY day, d.System ORDER BY day, event_cnt DESC;
SELECT d.Name AS name_entity, COUNT(*) AS event_cnt FROM DEPS_DEV_V1.DEPENDENTS d WHERE FROM_UNIXTIME(d.SnapshotAt / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(d.SnapshotAt / 1000000) < '2026-01-31 23:59:59' GROUP BY d.Name HAVING COUNT(*) >= 10 ORDER BY event_cnt DESC;
WITH topic_cnt AS ( SELECT d.System AS topic, COUNT(*) AS cnt FROM DEPS_DEV_V1.DEPENDENTS d WHERE FROM_UNIXTIME(d.SnapshotAt / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(d.SnapshotAt / 1000000) < '2026-01-31 23:59:59' GROUP BY d.System ), avg_cnt AS ( SELECT AVG(cnt) AS avg_cnt FROM topic_cnt ) SELECT topic, cnt FROM topic_cnt WHERE cnt > (SELECT avg_cnt FROM avg_cnt) ORDER BY cnt DESC LIMIT 10;
SELECT o.id AS id_external FROM GHCN_D.GHCND_2018 o WHERE o.date >= '2018-01-01 00:00:00' AND o.date < '2019-01-01 00:00:00' ORDER BY o.date DESC LIMIT 10;
SELECT o.id AS id_external FROM GHCN_D.GHCND_2018 o WHERE o.sflag = '7' ORDER BY o.date DESC LIMIT 10;
SELECT COUNT(*) AS event_cnt FROM GHCN_D.GHCND_2018 o WHERE o.date >= '2018-01-01 00:00:00' AND o.date < '2019-01-01 00:00:00';
SELECT SUM(o.value) AS total_amount FROM GHCN_D.GHCND_2018 o WHERE o.date >= '2018-01-01 00:00:00' AND o.date < '2019-01-01 00:00:00';
SELECT AVG(o.value) AS avg_amount FROM GHCN_D.GHCND_2018 o WHERE o.date >= '2018-01-01 00:00:00' AND o.date < '2019-01-01 00:00:00';
SELECT st.name AS name_entity, COUNT(*) AS event_cnt FROM GHCN_D.GHCND_2018 o JOIN GHCN_D.GHCND_STATIONS st ON st.id = o.id WHERE o.date >= '2018-01-01 00:00:00' AND o.date < '2018-07-01 00:00:00' GROUP BY st.name ORDER BY event_cnt DESC LIMIT 10;
SELECT st.name AS name_entity, SUM(o.value) AS total_amount FROM GHCN_D.GHCND_2018 o JOIN GHCN_D.GHCND_STATIONS st ON st.id = o.id WHERE o.date >= '2018-01-01 00:00:00' AND o.date < '2018-07-01 00:00:00' GROUP BY st.name ORDER BY total_amount DESC LIMIT 10;
SELECT CONCAT(CAST(st.latitude AS CHAR), ',', CAST(st.longitude AS CHAR)) AS location, COUNT(*) AS event_cnt FROM GHCN_D.GHCND_2018 o JOIN GHCN_D.GHCND_STATIONS st ON st.id = o.id WHERE o.date >= '2018-01-01 00:00:00' AND o.date < '2018-07-01 00:00:00' GROUP BY location ORDER BY event_cnt DESC LIMIT 10;
SELECT DATE(o.date) AS day, COUNT(*) AS event_cnt FROM GHCN_D.GHCND_2018 o WHERE o.date >= '2018-01-01 00:00:00' AND o.date < '2019-01-01 00:00:00' GROUP BY day ORDER BY day;
SELECT DATE_FORMAT(o.date, '%Y-%m-01') AS month, SUM(o.value) AS total_amount FROM GHCN_D.GHCND_2018 o WHERE o.date >= '2018-01-01 00:00:00' AND o.date < '2019-01-01 00:00:00' GROUP BY month ORDER BY month;
SELECT st.name AS name_entity, COUNT(*) AS event_cnt FROM GHCN_D.GHCND_2018 o JOIN GHCN_D.GHCND_STATIONS st ON st.id = o.id WHERE o.date >= '2018-01-01 00:00:00' AND o.date < '2018-07-01 00:00:00' GROUP BY st.name HAVING COUNT(*) >= 10 ORDER BY event_cnt DESC;
SELECT st.name AS name_entity, AVG(o.value) AS avg_amount FROM GHCN_D.GHCND_2018 o JOIN GHCN_D.GHCND_STATIONS st ON st.id = o.id WHERE o.date >= '2018-01-01 00:00:00' AND o.date < '2018-07-01 00:00:00' AND o.value IS NOT NULL GROUP BY st.name ORDER BY avg_amount DESC LIMIT 10;
SELECT p.consecutive_number AS id_external FROM NHTSA_TRAFFIC_FATALITIES_PLUS.NHTSA_TRAFFIC_FATALITIES_PERSON_2016 p WHERE p.injury_severity_name LIKE '%Fatal%' ORDER BY p.timestamp_of_crash DESC LIMIT 10;
SELECT a.consecutive_number AS id_external FROM NHTSA_TRAFFIC_FATALITIES_PLUS.NHTSA_TRAFFIC_FATALITIES_ACCIDENT_2016 a WHERE FROM_UNIXTIME(a.timestamp_of_crash / 1000000) >= '2016-01-01 00:00:00' AND FROM_UNIXTIME(a.timestamp_of_crash / 1000000) < '2016-12-31 23:59:59' ORDER BY a.timestamp_of_crash DESC LIMIT 10;
SELECT p.consecutive_number AS id_external FROM NHTSA_TRAFFIC_FATALITIES_PLUS.NHTSA_TRAFFIC_FATALITIES_PERSON_2016 p WHERE p.alcohol_test_status1 = 'Test Given' ORDER BY p.timestamp_of_crash DESC LIMIT 10;
SELECT p.consecutive_number AS id_external FROM NHTSA_TRAFFIC_FATALITIES_PLUS.NHTSA_TRAFFIC_FATALITIES_PERSON_2016 p WHERE FROM_UNIXTIME(p.timestamp_of_crash / 1000000) >= '2016-05-01 00:00:00' AND FROM_UNIXTIME(p.timestamp_of_crash / 1000000) < '2016-07-31 23:59:59' AND p.alcohol_test_status1 = 'Test Given' AND p.injury_severity_name LIKE CONCAT('%', 'Fatal', '%') ORDER BY p.timestamp_of_crash DESC LIMIT 10;
SELECT COUNT(*) AS event_cnt FROM NHTSA_TRAFFIC_FATALITIES_PLUS.NHTSA_TRAFFIC_FATALITIES_ACCIDENT_2016 a WHERE FROM_UNIXTIME(a.timestamp_of_crash / 1000000) >= '2016-01-01 00:00:00' AND FROM_UNIXTIME(a.timestamp_of_crash / 1000000) < '2016-12-31 23:59:59';
SELECT COUNT(DISTINCT v.vehicle_make) AS distinct_entity_cnt FROM NHTSA_TRAFFIC_FATALITIES_PLUS.NHTSA_TRAFFIC_FATALITIES_VEHICLE_2016 v WHERE FROM_UNIXTIME(v.timestamp_of_crash / 1000000) >= '2016-01-01 00:00:00' AND FROM_UNIXTIME(v.timestamp_of_crash / 1000000) < '2016-12-31 23:59:59';
SELECT AVG(a.number_of_fatalities) AS avg_quantity FROM NHTSA_TRAFFIC_FATALITIES_PLUS.NHTSA_TRAFFIC_FATALITIES_ACCIDENT_2016 a WHERE FROM_UNIXTIME(a.timestamp_of_crash / 1000000) >= '2016-01-01 00:00:00' AND FROM_UNIXTIME(a.timestamp_of_crash / 1000000) < '2016-12-31 23:59:59';
SELECT a.state_name AS name_entity, COUNT(*) AS event_cnt FROM NHTSA_TRAFFIC_FATALITIES_PLUS.NHTSA_TRAFFIC_FATALITIES_ACCIDENT_2016 a WHERE FROM_UNIXTIME(a.timestamp_of_crash / 1000000) >= '2016-01-01 00:00:00' AND FROM_UNIXTIME(a.timestamp_of_crash / 1000000) < '2016-12-31 23:59:59' GROUP BY a.state_name ORDER BY event_cnt DESC LIMIT 10;
SELECT pb.pedestrian_position AS location, COUNT(*) AS event_cnt FROM NHTSA_TRAFFIC_FATALITIES_PLUS.NHTSA_TRAFFIC_FATALITIES_PBTYPE_2016 pb JOIN NHTSA_TRAFFIC_FATALITIES_PLUS.NHTSA_TRAFFIC_FATALITIES_ACCIDENT_2016 a ON a.consecutive_number = pb.consecutive_number WHERE FROM_UNIXTIME(a.timestamp_of_crash / 1000000) >= '2016-01-01 00:00:00' AND FROM_UNIXTIME(a.timestamp_of_crash / 1000000) < '2016-12-31 23:59:59' GROUP BY pb.pedestrian_position ORDER BY event_cnt DESC LIMIT 10;
SELECT v.registered_vehicle_owner AS rel_person, COUNT(*) AS event_cnt FROM NHTSA_TRAFFIC_FATALITIES_PLUS.NHTSA_TRAFFIC_FATALITIES_VEHICLE_2016 v WHERE FROM_UNIXTIME(v.timestamp_of_crash / 1000000) >= '2016-01-01 00:00:00' AND FROM_UNIXTIME(v.timestamp_of_crash / 1000000) < '2016-12-31 23:59:59' GROUP BY v.registered_vehicle_owner ORDER BY event_cnt DESC LIMIT 10;
SELECT DATE(FROM_UNIXTIME(a.timestamp_of_crash / 1000000.0)) AS day, COUNT(*) AS event_cnt FROM NHTSA_TRAFFIC_FATALITIES_PLUS.NHTSA_TRAFFIC_FATALITIES_ACCIDENT_2016 a WHERE FROM_UNIXTIME(a.timestamp_of_crash / 1000000) >= '2016-01-01 00:00:00' AND FROM_UNIXTIME(a.timestamp_of_crash / 1000000) < '2016-12-31 23:59:59' GROUP BY day ORDER BY day;
SELECT a.state_name AS name_entity, COUNT(*) AS event_cnt FROM NHTSA_TRAFFIC_FATALITIES_PLUS.NHTSA_TRAFFIC_FATALITIES_ACCIDENT_2016 a WHERE FROM_UNIXTIME(a.timestamp_of_crash / 1000000) >= '2016-01-01 00:00:00' AND FROM_UNIXTIME(a.timestamp_of_crash / 1000000) < '2016-12-31 23:59:59' GROUP BY a.state_name HAVING COUNT(*) >= 10 ORDER BY event_cnt DESC;
SELECT DISTINCT a.state_name AS name_entity FROM NHTSA_TRAFFIC_FATALITIES_PLUS.NHTSA_TRAFFIC_FATALITIES_VEHICLE_2016 v JOIN NHTSA_TRAFFIC_FATALITIES_PLUS.NHTSA_TRAFFIC_FATALITIES_ACCIDENT_2016 a ON a.consecutive_number = v.consecutive_number AND a.state_number = v.state_number WHERE FROM_UNIXTIME(v.timestamp_of_crash / 1000000) >= '2016-01-01 00:00:00' AND FROM_UNIXTIME(v.timestamp_of_crash / 1000000) < '2016-07-01 00:00:00' AND v.crash_type_name LIKE '%BACKING%' ORDER BY a.state_name LIMIT 10;
SELECT SUM(a.number_of_fatalities) AS total_quantity FROM NHTSA_TRAFFIC_FATALITIES_PLUS.NHTSA_TRAFFIC_FATALITIES_ACCIDENT_2016 a WHERE FROM_UNIXTIME(a.timestamp_of_crash / 1000000) >= '2016-01-01 00:00:00' AND FROM_UNIXTIME(a.timestamp_of_crash / 1000000) < '2016-01-31 23:59:59';
SELECT c.id AS id_external FROM STACKOVERFLOW.COMMENTS c WHERE c.text LIKE '%good%' ORDER BY c.id DESC LIMIT 10;
SELECT b.id AS id_external FROM STACKOVERFLOW.BADGES b WHERE FROM_UNIXTIME(b.date / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(b.date / 1000000) < '2026-01-31 23:59:59' ORDER BY b.date DESC LIMIT 10;
SELECT COUNT(*) AS event_cnt FROM STACKOVERFLOW.POSTS_MODERATOR_NOMINATION pmn WHERE FROM_UNIXTIME(pmn.last_activity_date / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(pmn.last_activity_date / 1000000) < '2026-01-31 23:59:59';
SELECT COUNT(DISTINCT p.parent_id) AS distinct_entity_cnt FROM STACKOVERFLOW.STACKOVERFLOW_POSTS p WHERE FROM_UNIXTIME(p.last_activity_date / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(p.last_activity_date / 1000000) < '2026-01-31 23:59:59';
SELECT AVG(p.comment_count) AS avg_quantity FROM STACKOVERFLOW.STACKOVERFLOW_POSTS p WHERE FROM_UNIXTIME(p.last_activity_date / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(p.last_activity_date / 1000000) < '2026-01-31 23:59:59';
SELECT pmn.tags AS category_topic, COUNT(*) AS event_cnt FROM STACKOVERFLOW.POSTS_MODERATOR_NOMINATION pmn WHERE FROM_UNIXTIME(pmn.last_activity_date / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(pmn.last_activity_date / 1000000) < '2026-01-31 23:59:59' GROUP BY pmn.tags ORDER BY event_cnt DESC LIMIT 10;
SELECT pmn.title AS name_entity, COUNT(*) AS event_cnt FROM STACKOVERFLOW.POSTS_MODERATOR_NOMINATION pmn WHERE FROM_UNIXTIME(pmn.last_activity_date / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(pmn.last_activity_date / 1000000) < '2026-01-31 23:59:59' GROUP BY pmn.title ORDER BY event_cnt DESC LIMIT 10;
SELECT b.user_id AS rel_person, COUNT(*) AS event_cnt FROM STACKOVERFLOW.BADGES b WHERE FROM_UNIXTIME(b.date / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(b.date / 1000000) < '2026-01-31 23:59:59' GROUP BY b.user_id ORDER BY event_cnt DESC LIMIT 10;
SELECT DATE(FROM_UNIXTIME(p.last_activity_date / 1000000.0)) AS day, COUNT(*) AS event_cnt FROM STACKOVERFLOW.STACKOVERFLOW_POSTS p WHERE FROM_UNIXTIME(p.last_activity_date / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(p.last_activity_date / 1000000) < '2026-01-31 23:59:59' GROUP BY day ORDER BY day;
SELECT DATE(FROM_UNIXTIME(p.last_activity_date / 1000000.0)) AS day, p.post_type_id AS category_topic, COUNT(*) AS event_cnt FROM STACKOVERFLOW.STACKOVERFLOW_POSTS p WHERE FROM_UNIXTIME(p.last_activity_date / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(p.last_activity_date / 1000000) < '2026-01-31 23:59:59' GROUP BY day, p.post_type_id ORDER BY day, event_cnt DESC;
SELECT CAST(b.user_id AS CHAR) AS name_entity, COUNT(*) AS event_cnt FROM STACKOVERFLOW.BADGES b WHERE FROM_UNIXTIME(b.date / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(b.date / 1000000) < '2026-01-31 23:59:59' GROUP BY CAST(b.user_id AS CHAR) HAVING COUNT(*) >= 5 ORDER BY event_cnt DESC;
WITH topic_cnt AS ( SELECT p.post_type_id AS topic, COUNT(*) AS cnt FROM STACKOVERFLOW.STACKOVERFLOW_POSTS p WHERE FROM_UNIXTIME(p.last_activity_date / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(p.last_activity_date / 1000000) < '2026-01-31 23:59:59' GROUP BY p.post_type_id ), avg_cnt AS ( SELECT AVG(cnt) AS avg_cnt FROM topic_cnt ) SELECT topic, cnt FROM topic_cnt WHERE cnt > (SELECT avg_cnt FROM avg_cnt) ORDER BY cnt DESC LIMIT 10;
SELECT pmn.owner_user_id AS rel_person, pmn.tags AS category_topic, COUNT(*) AS event_cnt FROM STACKOVERFLOW.POSTS_MODERATOR_NOMINATION pmn WHERE FROM_UNIXTIME(pmn.last_activity_date / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(pmn.last_activity_date / 1000000) < '2026-01-31 23:59:59' GROUP BY pmn.owner_user_id, pmn.tags ORDER BY event_cnt DESC LIMIT 10;
SELECT CAST(b.tag_based AS CHAR) AS category_topic, CAST(SUM(CASE WHEN b.tag_based = 'Business' THEN 1 ELSE 0 END) AS DOUBLE) / COUNT(*) AS ratio_in_status FROM STACKOVERFLOW.BADGES b WHERE FROM_UNIXTIME(b.date / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(b.date / 1000000) < '2026-01-31 23:59:59' GROUP BY CAST(b.tag_based AS CHAR) ORDER BY ratio_in_status DESC LIMIT 10;
SELECT SUM(p.comment_count) AS total_quantity FROM STACKOVERFLOW.STACKOVERFLOW_POSTS p WHERE FROM_UNIXTIME(p.last_activity_date / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(p.last_activity_date / 1000000) < '2026-01-31 23:59:59';
SELECT p.tags AS category_topic, SUM(p.view_count) AS total_quantity FROM STACKOVERFLOW.STACKOVERFLOW_POSTS p WHERE FROM_UNIXTIME(p.last_activity_date / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(p.last_activity_date / 1000000) < '2026-01-31 23:59:59' GROUP BY p.tags ORDER BY total_quantity DESC LIMIT 10;
SELECT COUNT(*) AS row_cnt FROM DEPS_DEV_V1.ADVISORIES;
SELECT element, SUM(value) AS total_amount FROM GHCN_D.GHCND_1763 WHERE CAST(date AS DATETIME) >= '2001-01-01 00:00:00' AND CAST(date AS DATETIME) < '2026-01-31 23:59:59' GROUP BY element ORDER BY total_amount DESC LIMIT 10;
SELECT COUNT(DISTINCT SourceID) AS distinct_external_cnt FROM DEPS_DEV_V1.ADVISORIES;
SELECT element, SUM(value) AS total_amount FROM GHCN_D.GHCND_1763 WHERE CAST(date AS DATETIME) >= '2001-01-01 00:00:00' AND CAST(date AS DATETIME) < '2026-01-31 23:59:59' GROUP BY element HAVING SUM(value) >= 1000 ORDER BY total_amount DESC;
SELECT COUNT(DISTINCT Packages) AS distinct_entity_cnt FROM DEPS_DEV_V1.ADVISORIES;
SELECT latitude, COUNT(DISTINCT id) AS distinct_external_cnt FROM GHCN_D.GHCND_INVENTORY GROUP BY latitude ORDER BY distinct_external_cnt DESC LIMIT 10;
SELECT Packages, COUNT(*) AS event_cnt FROM DEPS_DEV_V1.ADVISORIES GROUP BY Packages ORDER BY event_cnt DESC LIMIT 10;
SELECT body_type_name, COUNT(*) AS event_cnt FROM NHTSA_TRAFFIC_FATALITIES_PLUS.NHTSA_TRAFFIC_FATALITIES_PARKWORK_2015 GROUP BY body_type_name ORDER BY event_cnt DESC LIMIT 10;
SELECT SourceID FROM DEPS_DEV_V1.ADVISORIES WHERE Title LIKE '%application%' ORDER BY SourceID LIMIT 10;
SELECT relation_to_trafficway, SUM(number_of_persons_in_motor_vehicles_in_transport_mvit) AS total_quantity FROM NHTSA_TRAFFIC_FATALITIES_PLUS.NHTSA_TRAFFIC_FATALITIES_ACCIDENT_2020 GROUP BY relation_to_trafficway ORDER BY total_quantity DESC LIMIT 10;
